import { spawnSync } from 'node:child_process';
import { statSync, accessSync, constants } from 'node:fs';
import { join } from 'node:path';

export const REFUSED = 2;

/** Resolve a plugin name to its script path. */
export function pluginPath(root, name) {
  return join(root, 'plugins', `${name}.sh`);
}

/** Refuse to run a plugin, naming it on stderr. The plugin never starts. */
function refuse(name) {
  process.stderr.write(`plugin ${name} cannot be run\n`);
  return REFUSED;
}

/**
 * Run a plugin, returning its exit code.
 *
 * Fails closed with REFUSED (without ever starting the plugin) whenever the
 * script can't actually be handed to bash: missing, not a regular file,
 * unreadable, or the interpreter itself can't be launched. Once the plugin
 * has actually started, its own exit code is always propagated.
 */
export function runPlugin(root, name, args = []) {
  const script = pluginPath(root, name);

  let stat;
  try {
    stat = statSync(script);
  } catch {
    return refuse(name);
  }
  if (!stat.isFile()) {
    return refuse(name);
  }
  try {
    accessSync(script, constants.R_OK);
  } catch {
    return refuse(name);
  }

  const run = spawnSync('bash', [script, ...args], { encoding: 'utf8' });
  if (run.error) {
    return refuse(name);
  }
  if (run.stdout) process.stdout.write(run.stdout);
  if (run.stderr) process.stderr.write(run.stderr);
  if (run.status === null) {
    return refuse(name);
  }
  return run.status;
}

