import { test } from 'node:test';
import assert from 'node:assert/strict';
import { runPlugin, REFUSED } from '../src/launcher.mjs';

const root = process.cwd();

/** Run `fn` with process.stderr.write captured; returns [result, capturedText]. */
function captureStderr(fn) {
  const original = process.stderr.write.bind(process.stderr);
  let captured = '';
  process.stderr.write = (chunk, ...rest) => {
    captured += chunk;
    return original(chunk, ...rest);
  };
  try {
    return [fn(), captured];
  } finally {
    process.stderr.write = original;
  }
}

test('a working plugin runs and its exit code is 0', () => {
  assert.equal(runPlugin(root, 'hello'), 0);
});

test("a failing plugin's own exit code is propagated", () => {
  assert.equal(runPlugin(root, 'fails'), 7);
});

test('a plugin that does not exist is refused', () => {
  assert.equal(runPlugin(root, 'absent'), REFUSED);
});

test('a plugin path that is a directory is refused, not handed to bash', () => {
  const [result, stderr] = captureStderr(() => runPlugin(root, 'isdir'));
  assert.equal(result, REFUSED);
  assert.match(stderr, /isdir/);
});

test('the refusal message names the missing plugin', () => {
  const [result, stderr] = captureStderr(() => runPlugin(root, 'absent'));
  assert.equal(result, REFUSED);
  assert.match(stderr, /absent/);
});

test('a plugin is refused, with no output, when the interpreter cannot be launched', () => {
  const originalPath = process.env.PATH;
  process.env.PATH = '';
  let result, stderr, stdout;
  const originalStdoutWrite = process.stdout.write.bind(process.stdout);
  let capturedStdout = '';
  process.stdout.write = (chunk, ...rest) => {
    capturedStdout += chunk;
    return originalStdoutWrite(chunk, ...rest);
  };
  try {
    [result, stderr] = captureStderr(() => runPlugin(root, 'hello'));
  } finally {
    process.stdout.write = originalStdoutWrite;
    process.env.PATH = originalPath;
  }
  stdout = capturedStdout;
  assert.equal(result, REFUSED);
  assert.match(stderr, /hello/);
  assert.equal(stdout, '');
});

